// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the arrays length and a single recipient address and value; the fuzzer will provide many combos
    function testFuzz_property(address to, uint256 v, uint256 len) public {
        // keep length reasonable but allow zero/large to be explored; require >0 because contract requires it
        uint256 l = bound(len, 1, 5);

        // prepare arrays
        address[] memory tos = new address[](l);
        uint256[] memory vals = new uint256[](l);
        for (uint i = 0; i < l; i++) {
            tos[i] = to;
            vals[i] = v;
        }

        // call as the required sender
        address requiredSender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.startPrank(requiredSender);
        bool okRef;
        // capture whether call completed and the returned boolean for the reference via try/catch
        try c.transfer(tos, vals) returns (bool ret) {
            okRef = ret; // if it returns, record returned value
        } catch {
            // if it reverts, we mark as revert by setting okRef to false but also will assert based on completion
            okRef = false;
        }
        vm.stopPrank();

        // The general rule: if transfer completes (i.e., does not revert) then it returns true.
        // We express this as: okRef == true for all admissible inputs where call returned normally.
        // Because try/catch collapsed both revert and return into okRef==false for revert, this assertion
        // effectively requires that any non-reverting invocation yields true. If the mutant returns false
        // while still completing, this assertion will fail on that input.
        assertTrue(okRef == true);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // helper callee that always succeeds for transferFrom selector
    contract SuccessCallee {
        // accept any calldata and return true-ish behavior (do nothing)
        fallback() external payable {}
    }

    function setUp() public { c = new C(); }

    // fuzz the receiving address and one value; the adversarial counterparty is deployed below
    function testFuzz_property(address to, uint256 val) public {
        // keep to non-zero and val within reasonable bounds to avoid overflow on multiplication
        vm.assume(to != address(0));
        // bound val so v[i] * 1e18 doesn't overflow uint256
        val = bound(val, 0, type(uint256).max / 1000000000000000000);

        // Deploy a callee that will be used as caddress via storage replacement is NOT allowed.
        // The contract C has a hardcoded caddress; we cannot change it. However, the reference
        // behavior difference is solely in the return value of transfer when it completes.
        // We therefore simply call transfer with parameters that satisfy preconditions and
        // the low-level call to caddress (an EOA) will succeed (as fuzzed address may be EOA).
        // To ensure the call to caddress succeeds, we must supply arrays of length > 0.

        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory vals = new uint[](1);
        vals[0] = val;

        // The reference contract requires msg.sender == from. Use vm.prank to call as that address.
        address from = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(from);

        // Call and capture whether it returned true. Because Solidity external call returns the bool,
        // we use try/catch on low-level call to determine success and then assert the returned value is true.
        bool ok;
        try c.transfer(tos, vals) returns (bool r) {
            ok = r;
        } catch {
            // If it reverts, set ok = false; but reference C should not revert when inputs satisfy assumptions
            ok = false;
        }

        // The universal property: for all admissible inputs (we ensured tos non-empty and caller is from),
        // the reference C returns true on successful completion. The mutant that returns false will fail this assert
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: an address for a recipient (the fuzzer can try many), and a uint amount
    function testFuzz_property(address to, uint256 amount) public {
        // keep inputs admissible: non-zero recipient and small-ish array size simulated by single-item arrays
        vm.assume(to != address(0));
        // prepare single-element arrays
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory vals = new uint[](1);
        vals[0] = amount;

        // the contract requires msg.sender to be the hardcoded address; impersonate it
        address owner = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(owner);

        // call and capture whether it returns true via try/catch and return data
        bool ok;
        try c.transfer(tos, vals) returns (bool ret) {
            // in the correct contract ret must be true for all admissible inputs
            ok = ret;
        } catch {
            // should not revert for admissible inputs (owner caller and non-empty tos)
            ok = false;
        }

        // Single assertion: reference contract always returns true (the mutant will cause some inputs to return false)
        assertTrue(ok);
    }
}
